 articles.append(dict(slug=slug,category=cat,title=title,summary=summary,analogy=analogy,nodes=nodes.split('|'),sections=[dict(title=t,text=p) for t,p in sections],example=example,pitfall=pitfall,question=question,answer=answer,sources=[dict(title=t,url=u) for t,u in sources],tags=tags.split(' '),requires=requires,date='2026-11-04'))
